  //**/
  printf("Thank you. Now enter student score (percent) >");
  scanf("%f", &percent);

  //**/
  grade = user_grade(percent, a, b, c, d);

  //**/
  if (grade == 'F')
    printf("Student has failed the course\n");
  else
    printf("Student has an %c grade\n", grade);

  return (0);

}

